                f.write(gzip.compress(raw, mtime=0) if ent.get("gz") else raw)
            os.chmod(full, 0o755 if ent.get("x") else 0o644)
            os.utime(full, (ent.get("m", EPOCH), ent.get("m", EPOCH)))
