    spec = json.load(open(os.path.join(repo, "tests", "spec.json"), encoding="utf-8"))
    script = os.path.join(repo, spec["script"])
    if not os.path.isfile(script):
        print(f"FAIL: {spec['script']} does not exist")
        sys.exit(1)
